#!/usr/bin/env python3
"""Validate wrestling animation JSON libraries without modifying original files."""
import json
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
DATA = ROOT / "Assets" / "ImportedOriginal" / "RingClash3D" / "Data" / "Animations"
CHARACTERS = ("aj", "orton", "boxer", "runner")
errors = []
report = [
    "# Animation library validation",
    "",
    "Generated by Tools/validate_animation_libraries.py.",
    "Original JSON files are read-only; this script does not rewrite them.",
    "",
]

for character in CHARACTERS:
    path = DATA / f"{character}.json"
    if not path.is_file():
        errors.append(f"{character}: missing file {path}")
        continue
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        errors.append(f"{character}: invalid JSON: {exc}")
        continue

    skeleton = data.get("bones")
    clips = data.get("clips")
    if not isinstance(skeleton, list) or not skeleton:
        errors.append(f"{character}: top-level bones must be a non-empty list")
        skeleton = []
    if not isinstance(clips, dict) or not clips:
        errors.append(f"{character}: clips must be a non-empty object")
        clips = {}

    report += [f"## {character.upper()}", "",
               f"- Skeleton bones: {len(skeleton)}",
               f"- Animation clips: {len(clips)}"]
    bad_clips = 0
    paired = set()

    for clip_name, clip in clips.items():
        if not isinstance(clip, dict):
            errors.append(f"{character}/{clip_name}: clip is not an object")
            bad_clips += 1
            continue
        frames, fps, duration = clip.get("n"), clip.get("fps"), clip.get("len")
        tracks = clip.get("bones")
        if not isinstance(frames, int) or frames < 2:
            errors.append(f"{character}/{clip_name}: invalid frame count {frames!r}")
            bad_clips += 1
            continue
        if not isinstance(fps, (int, float)) or fps <= 0:
            errors.append(f"{character}/{clip_name}: invalid fps {fps!r}")
            bad_clips += 1
        if not isinstance(duration, (int, float)) or duration <= 0:
            errors.append(f"{character}/{clip_name}: invalid duration {duration!r}")
            bad_clips += 1
        if not isinstance(tracks, dict) or not tracks:
            errors.append(f"{character}/{clip_name}: missing bone tracks")
            bad_clips += 1
            continue

        for bone_name, values in tracks.items():
            if bone_name not in skeleton:
                errors.append(f"{character}/{clip_name}: unknown bone {bone_name}")
                bad_clips += 1
            elif not isinstance(values, list) or len(values) != frames * 4:
                actual = len(values) if isinstance(values, list) else "non-list"
                errors.append(f"{character}/{clip_name}/{bone_name}: expected {frames*4} quaternion values, got {actual}")
                bad_clips += 1

        root = clip.get("root")
        if not isinstance(root, list) or len(root) != frames * 3:
            actual = len(root) if isinstance(root, list) else "missing/non-list"
            errors.append(f"{character}/{clip_name}: root expected {frames*3} values, got {actual}")
            bad_clips += 1
        rm = clip.get("rm")
        if rm is not None and (not isinstance(rm, list) or len(rm) != frames * 2):
            actual = len(rm) if isinstance(rm, list) else "non-list"
            errors.append(f"{character}/{clip_name}: root-motion expected {frames*2} values, got {actual}")
            bad_clips += 1

        if clip_name.startswith(("t_", "d_")):
            paired.add(clip_name[2:])

    complete_pairs = sorted(move for move in paired
                            if f"t_{move}" in clips and f"d_{move}" in clips)
    report += [f"- Clips with structural issues: {bad_clips}",
               f"- Complete performer/receiver move pairs: {len(complete_pairs)}",
               "", "Paired moves: " + (", ".join(complete_pairs) if complete_pairs else "None detected"), ""]

report += ["## Result", ""]
if errors:
    report += [f"FAILED — {len(errors)} issue(s).", ""] + [f"- {e}" for e in errors]
else:
    report += ["PASSED — all four libraries passed structural validation."]
(ROOT / "AnimationValidationReport.md").write_text("\n".join(report) + "\n", encoding="utf-8")
print("\n".join(report))
if errors:
    sys.exit(1)
